Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Capacity demo</span>
<label>Number of hidden units: <output id="hiddenUnitCountVal">6</output><input id="hiddenUnitCountInput" type="range" min="6" max="50" step="1" value="6" oninput="document.getElementById('hiddenUnitCountVal').value=this.value;update_hiddenUnitCount(+this.value)"></label>
<label><input id="fitComparisonInput" type="checkbox" onchange="toggle_fitComparison(this.checked)"> Compare capacity extremes</label>
<button onclick="trigger_resetView()">Show all panels</button>
<span id="demoNarration" style="margin:0;font-size:10px;max-width:180px;line-height:1.25">The orange points are the training observations, while the black curve shows the smooth underlying relationship the model is trying to approximate.</span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 5</span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

var ORANGE = '#cf7654';
var CYAN = '#9fdad7';
var BLACK = '#000000';
var GREY = '#777777';

var trainPts = [
  [0.035, -0.08],
  [0.12, 0.19],
  [0.19, 0.47],
  [0.81, -0.66],
  [0.92, -0.42],
  [0.98, -0.47]
];

var targetAnchors = [
  [0.00, -0.28], [0.06, -0.08], [0.12, 0.19], [0.20, 0.55],
  [0.28, 0.56], [0.38, 0.20], [0.50, -0.25], [0.62, -0.51],
  [0.76, -0.60], [0.88, -0.53], [1.00, -0.25]
];

var fitAnchors = {
  6: [[0.00,-0.18],[0.08,0.05],[0.14,0.22],[0.21,0.50],[0.28,1.02],[0.34,1.18],[0.43,0.55],[0.52,-0.55],[0.60,-1.25],[0.76,-1.18],[0.83,-0.42],[0.92,-0.46],[1.00,-0.44]],
  7: [[0.00,-0.15],[0.08,0.07],[0.14,0.22],[0.28,0.90],[0.43,0.35],[0.57,-0.60],[0.68,-1.02],[0.76,-1.06],[0.86,-0.40],[0.92,-0.43],[1.00,-0.48]],
  8: [[0.00,-0.15],[0.08,0.07],[0.14,0.22],[0.25,0.75],[0.38,0.55],[0.50,-0.12],[0.63,-0.63],[0.75,-0.84],[0.87,-0.40],[0.93,-0.43],[1.00,-0.48]],
  10: [[0.00,-0.17],[0.08,0.05],[0.14,0.22],[0.24,0.52],[0.31,0.56],[0.40,0.40],[0.52,0.02],[0.63,-0.38],[0.74,-0.58],[0.83,-0.62],[0.91,-0.42],[1.00,-0.47]],
  50: [[0.00,-0.16],[0.06,-0.04],[0.12,0.20],[0.20,0.49],[0.27,0.61],[0.37,0.54],[0.49,0.16],[0.60,-0.25],[0.70,-0.50],[0.78,-0.68],[0.86,-0.62],[0.92,-0.43],[1.00,-0.46]]
};

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

function catmullAt(pts, x) {
  if (x <= pts[0][0]) return pts[0][1];
  if (x >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  var i = 0;
  while (i < pts.length - 2 && pts[i + 1][0] < x) i++;
  var p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
  var t = (x - p1[0]) / (p2[0] - p1[0]);
  var t2 = t * t, t3 = t2 * t;
  return 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2*p0[1] - 5*p1[1] + 4*p2[1] - p3[1]) * t2 + (-p0[1] + 3*p1[1] - 3*p2[1] + p3[1]) * t3);
}

function linearAt(pts, x) {
  if (x <= pts[0][0]) return pts[0][1];
  if (x >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  for (var i = 0; i < pts.length - 1; i++) {
    if (x >= pts[i][0] && x <= pts[i + 1][0]) {
      var t = (x - pts[i][0]) / (pts[i + 1][0] - pts[i][0]);
      return pts[i][1] * (1 - t) + pts[i + 1][1] * t;
    }
  }
  return pts[pts.length - 1][1];
}

function targetY(x) { return catmullAt(targetAnchors, x); }

function fitYForUnits(units, x) {
  units = clamp(units, 6, 50);
  if (fitAnchors[units]) {
    return units === 50 ? catmullAt(fitAnchors[50], x) : linearAt(fitAnchors[units], x);
  }
  var lower, upper;
  if (units < 7) { lower = 6; upper = 7; }
  else if (units < 8) { lower = 7; upper = 8; }
  else if (units < 10) { lower = 8; upper = 10; }
  else { lower = 10; upper = 50; }
  var t = (units - lower) / (upper - lower);
  var yl = lower === 50 ? catmullAt(fitAnchors[50], x) : linearAt(fitAnchors[lower], x);
  var yu = upper === 50 ? catmullAt(fitAnchors[50], x) : linearAt(fitAnchors[upper], x);
  return yl * (1 - t) + yu * t;
}

var state = {
  focused: null,
  selectedUnits: 6,
  compare: false,
  step: 0
};

var lastPanels = [];

function layoutPanels(w, h, focused) {
  var s = Math.min(w, h);
  var left = Math.max(42, s * 0.09);
  var right = Math.max(10, s * 0.018);
  var top = Math.max(34, s * 0.07);
  var bottom = Math.max(45, s * 0.085);
  if (focused) {
    return [{
      x: left, y: top,
      w: Math.max(20, w - left - right),
      h: Math.max(20, h - top - bottom),
      index: focused.index == null ? -1 : focused.index,
      units: focused.units,
      letter: focused.letter || '',
      title: focused.title || ''
    }];
  }
  var gx = Math.max(18, w * 0.033);
  var gy = Math.max(58, h * 0.115);
  var pw = (w - left - right - 2 * gx) / 3;
  var ph = (h - top - bottom - gy) / 2;
  var panels = [];
  var letters = ['a)', 'b)', 'c)', 'd)', 'e)', 'f)'];
  var titles = ['', '6 hidden units', '7 hidden units', '8 hidden units', '10 hidden units', '50 hidden units'];
  var units = [null, 6, 7, 8, 10, 50];
  for (var r = 0; r < 2; r++) {
    for (var c = 0; c < 3; c++) {
      var idx = r * 3 + c;
      panels.push({
        x: left + c * (pw + gx),
        y: top + r * (ph + gy),
        w: pw,
        h: ph,
        index: idx,
        units: units[idx],
        letter: letters[idx],
        title: titles[idx]
      });
    }
  }
  return panels;
}

function panelScale(panel) {
  return {
    x: function(v) { return panel.x + v * panel.w; },
    y: function(v) { return panel.y + panel.h - ((v + 1) / 2) * panel.h; }
  };
}

function drawPolyline(ctx, panel, pts, color, width, alpha) {
  var sc = panelScale(panel);
  ctx.save();
  ctx.beginPath();
  ctx.rect(panel.x, panel.y, panel.w, panel.h);
  ctx.clip();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    var px = sc.x(pts[i][0]), py = sc.y(pts[i][1]);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();
}

function sampledPts(fn, n) {
  var pts = [];
  for (var i = 0; i < n; i++) {
    var x = i / (n - 1);
    pts.push([x, fn(x)]);
  }
  return pts;
}

function fitPts(units) {
  if (fitAnchors[units] && units !== 50) return fitAnchors[units];
  var n = units >= 35 ? 150 : 80;
  return sampledPts(function(x) { return fitYForUnits(units, x); }, n);
}

function drawAxes(ctx, panel, row, col, fontBase) {
  var tickLen = Math.max(3, fontBase * 0.24);
  var minorLen = Math.max(2, fontBase * 0.16);
  ctx.save();

  if (state.compare && (panel.units === 6 || panel.units === 50)) {
    ctx.fillStyle = 'rgba(255, 232, 150, 0.22)';
    ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
  }

  ctx.strokeStyle = BLACK;
  ctx.lineWidth = Math.max(1.4, fontBase * 0.13);
  ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

  ctx.strokeStyle = GREY;
  ctx.lineWidth = Math.max(0.8, fontBase * 0.07);

  for (var i = 0; i <= 10; i++) {
    var x = panel.x + panel.w * i / 10;
    ctx.beginPath();
    ctx.moveTo(x, panel.y + panel.h);
    ctx.lineTo(x, panel.y + panel.h + (i % 5 === 0 ? tickLen : minorLen));
    ctx.stroke();
  }
  for (var j = 0; j <= 10; j++) {
    var y = panel.y + panel.h * j / 10;
    ctx.beginPath();
    ctx.moveTo(panel.x, y);
    ctx.lineTo(panel.x - (j % 5 === 0 ? tickLen : minorLen), y);
    ctx.stroke();
  }

  ctx.fillStyle = GREY;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = Math.max(9, fontBase * 0.9) + 'px Arial, sans-serif';
  [0, 0.5, 1.0].forEach(function(v) {
    ctx.fillText(v.toFixed(1), panel.x + panel.w * v, panel.y + panel.h + tickLen + 2);
  });

  if (col === 0 || state.focused) {
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    [-1, 0, 1].forEach(function(v) {
      ctx.fillText(v.toFixed(1), panel.x - tickLen - 4, panel.y + panel.h - ((v + 1) / 2) * panel.h);
    });
  }

  ctx.restore();
}

function drawLabels(ctx, panels, w, h, focused, fontBase) {
  ctx.save();
  ctx.fillStyle = BLACK;

  panels.forEach(function(panel) {
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = Math.max(20, fontBase * 2.1) + 'px Arial, sans-serif';
    var lx = panel.x - Math.max(38, fontBase * 2.7);
    var ly = panel.y - Math.max(12, fontBase * 0.55);
    if (focused) {
      lx = panel.x - Math.max(30, fontBase * 2.1);
      ly = panel.y - Math.max(10, fontBase * 0.45);
    }
    ctx.fillText(panel.letter, lx, ly);

    if (panel.title) {
      ctx.textAlign = 'center';
      ctx.font = Math.max(18, fontBase * 2.05) + 'px Arial, sans-serif';
      ctx.fillText(panel.title, panel.x + panel.w / 2, panel.y - Math.max(10, fontBase * 0.45));
    }
  });

  var bottomPanels = focused ? panels : panels.filter(function(p) { return p.index >= 3; });
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = Math.max(18, fontBase * 1.95) + 'px Arial, sans-serif';
  bottomPanels.forEach(function(panel) {
    ctx.fillText('Input, ', panel.x + panel.w / 2 - fontBase * 0.35, panel.y + panel.h + Math.max(28, fontBase * 1.7));
    ctx.font = 'italic ' + Math.max(18, fontBase * 1.95) + 'px Georgia, serif';
    ctx.fillText('x', panel.x + panel.w / 2 + fontBase * 2.25, panel.y + panel.h + Math.max(28, fontBase * 1.7));
    ctx.font = Math.max(18, fontBase * 1.95) + 'px Arial, sans-serif';
  });

  var yLabelPanels = focused ? panels : [panels[0], panels[3]];
  yLabelPanels.forEach(function(panel) {
    ctx.save();
    ctx.translate(panel.x - Math.max(58, fontBase * 4.2), panel.y + panel.h / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = Math.max(18, fontBase * 1.9) + 'px Arial, sans-serif';
    ctx.fillText('Output, ', -fontBase * 0.55, 0);
    ctx.font = 'italic ' + Math.max(18, fontBase * 1.9) + 'px Georgia, serif';
    ctx.fillText('y', fontBase * 3.1, 0);
    ctx.restore();
  });

  ctx.restore();
}

function drawPanelContent(ctx, panel, fontBase) {
  var row = panel.index >= 3 ? 1 : 0;
  var col = panel.index < 0 ? 0 : panel.index % 3;
  var dim = state.compare && panel.units && panel.units !== 6 && panel.units !== 50 ? 0.28 : 1;

  drawAxes(ctx, panel, row, col, fontBase);

  drawPolyline(ctx, panel, sampledPts(targetY, 170), BLACK, Math.max(2.8, fontBase * 0.32), dim);

  if (panel.units) {
    var isExtreme = state.compare && (panel.units === 6 || panel.units === 50);
    drawPolyline(ctx, panel, fitPts(panel.units), CYAN, Math.max(2.7, fontBase * (isExtreme ? 0.38 : 0.32)), dim);
  }

  var sc = panelScale(panel);
  ctx.save();
  ctx.globalAlpha = dim;
  trainPts.forEach(function(p) {
    ctx.beginPath();
    ctx.arc(sc.x(p[0]), sc.y(p[1]), Math.max(3.5, Math.min(panel.w, panel.h) * 0.026), 0, Math.PI * 2);
    ctx.fillStyle = ORANGE;
    ctx.fill();
  });
  ctx.restore();
}

var capacityPlugin = {
  id: 'capacitySmallMultiples',
  afterDraw: function(chart) {
    var ctx = chart.ctx;
    var w = chart.width, h = chart.height;
    var fontBase = clamp(Math.min(w, h) / 42, 8, 17);

    ctx.save();
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);

    var focused = state.focused;
    var panels = layoutPanels(w, h, focused);
    lastPanels = panels;

    panels.forEach(function(panel) { drawPanelContent(ctx, panel, fontBase); });
    drawLabels(ctx, panels, w, h, focused, fontBase);

    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { display: false, min: 0, max: 1 },
      y: { display: false, min: 0, max: 1 }
    }
  },
  plugins: [capacityPlugin]
});
window.__markRendered();

function panelAtEvent(evt) {
  var r = canvas.getBoundingClientRect();
  var x = (evt.clientX - r.left) * (canvas.width / r.width);
  var y = (evt.clientY - r.top) * (canvas.height / r.height);
  for (var i = 0; i < lastPanels.length; i++) {
    var p = lastPanels[i];
    if (x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h) return p;
  }
  return null;
}

canvas.addEventListener('mousemove', function(evt) {
  var p = panelAtEvent(evt);
  if (p) {
    canvas.style.cursor = 'pointer';
    var name = p.index === 0 ? 'reference data and target function' : (p.units + ' hidden units');
    showTooltip('Click to inspect ' + name + '. Black: target trend; orange: training data; cyan: fitted network.', evt);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
