function drawAxes(ctx, panel, row, col, fontBase) {
  var tickLen = Math.max(3, fontBase * 0.24);
  var minorLen = Math.max(2, fontBase * 0.16);
  ctx.save();

  if (state.compare && (panel.units === 6 || panel.units === 50)) {
    ctx.fillStyle = 'rgba(255, 232, 150, 0.22)';
    ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
  }

  ctx.strokeStyle = BLACK;
  ctx.lineWidth = Math.max(1.4, fontBase * 0.13);
  ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

  ctx.strokeStyle = GREY;
  ctx.lineWidth = Math.max(0.8, fontBase * 0.07);

  for (var i = 0; i <= 10; i++) {
    var x = panel.x + panel.w * i / 10;
    ctx.beginPath();
    ctx.moveTo(x, panel.y + panel.h);
    ctx.lineTo(x, panel.y + panel.h + (i % 5 === 0 ? tickLen : minorLen));
    ctx.stroke();
  }
  for (var j = 0; j <= 10; j++) {
    var y = panel.y + panel.h * j / 10;
    ctx.beginPath();
    ctx.moveTo(panel.x, y);
    ctx.lineTo(panel.x - (j % 5 === 0 ? tickLen : minorLen), y);
    ctx.stroke();
  }

  ctx.fillStyle = GREY;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = Math.max(9, fontBase * 0.9) + 'px Arial, sans-serif';
  [0, 0.5, 1.0].forEach(function(v) {
    ctx.fillText(v.toFixed(1), panel.x + panel.w * v, panel.y + panel.h + tickLen + 2);
  });

  if (col === 0 || state.focused) {
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    [-1, 0, 1].forEach(function(v) {
      ctx.fillText(v.toFixed(1), panel.x - tickLen - 4, panel.y + panel.h - ((v + 1) / 2) * panel.h);
    });
  }

  ctx.restore();
}

function drawLabels(ctx, panels, w, h, focused, fontBase) {
  ctx.save();
  ctx.fillStyle = BLACK;

  panels.forEach(function(panel) {
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = Math.max(20, fontBase * 2.1) + 'px Arial, sans-serif';
    var lx = panel.x - Math.max(38, fontBase * 2.7);
    var ly = panel.y - Math.max(12, fontBase * 0.55);
    if (focused) {
      lx = panel.x - Math.max(30, fontBase * 2.1);
      ly = panel.y - Math.max(10, fontBase * 0.45);
    }
    ctx.fillText(panel.letter, lx, ly);

    if (panel.title) {
      ctx.textAlign = 'center';
      ctx.font = Math.max(18, fontBase * 2.05) + 'px Arial, sans-serif';
      ctx.fillText(panel.title, panel.x + panel.w / 2, panel.y - Math.max(10, fontBase * 0.45));
    }
  });

  var bottomPanels = focused ? panels : panels.filter(function(p) { return p.index >= 3; });
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = Math.max(18, fontBase * 1.95) + 'px Arial, sans-serif';
  bottomPanels.forEach(function(panel) {
    ctx.fillText('Input, ', panel.x + panel.w / 2 - fontBase * 0.35, panel.y + panel.h + Math.max(28, fontBase * 1.7));
    ctx.font = 'italic ' + Math.max(18, fontBase * 1.95) + 'px Georgia, serif';
    ctx.fillText('x', panel.x + panel.w / 2 + fontBase * 2.25, panel.y + panel.h + Math.max(28, fontBase * 1.7));
    ctx.font = Math.max(18, fontBase * 1.95) + 'px Arial, sans-serif';
  });

  var yLabelPanels = focused ? panels : [panels[0], panels[3]];
  yLabelPanels.forEach(function(panel) {
    ctx.save();
    ctx.translate(panel.x - Math.max(58, fontBase * 4.2), panel.y + panel.h / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = Math.max(18, fontBase * 1.9) + 'px Arial, sans-serif';
    ctx.fillText('Output, ', -fontBase * 0.55, 0);
    ctx.font = 'italic ' + Math.max(18, fontBase * 1.9) + 'px Georgia, serif';
    ctx.fillText('y', fontBase * 3.1, 0);
    ctx.restore();
  });

  ctx.restore();
}

function drawPanelContent(ctx, panel, fontBase) {
  var row = panel.index >= 3 ? 1 : 0;
  var col = panel.index < 0 ? 0 : panel.index % 3;
  var dim = state.compare && panel.units && panel.units !== 6 && panel.units !== 50 ? 0.28 : 1;

  drawAxes(ctx, panel, row, col, fontBase);

  drawPolyline(ctx, panel, sampledPts(targetY, 170), BLACK, Math.max(2.8, fontBase * 0.32), dim);

  if (panel.units) {
    var isExtreme = state.compare && (panel.units === 6 || panel.units === 50);
    drawPolyline(ctx, panel, fitPts(panel.units), CYAN, Math.max(2.7, fontBase * (isExtreme ? 0.38 : 0.32)), dim);
  }

  var sc = panelScale(panel);
  ctx.save();
  ctx.globalAlpha = dim;
  trainPts.forEach(function(p) {
    ctx.beginPath();
    ctx.arc(sc.x(p[0]), sc.y(p[1]), Math.max(3.5, Math.min(panel.w, panel.h) * 0.026), 0, Math.PI * 2);
    ctx.fillStyle = ORANGE;
    ctx.fill();
  });
  ctx.restore();
}

var capacityPlugin = {
  id: 'capacitySmallMultiples',
  afterDraw: function(chart) {
    var ctx = chart.ctx;
    var w = chart.width, h = chart.height;
    var fontBase = clamp(Math.min(w, h) / 42, 8, 17);

    ctx.save();
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);

    var focused = state.focused;
    var panels = layoutPanels(w, h, focused);
    lastPanels = panels;

    panels.forEach(function(panel) { drawPanelContent(ctx, panel, fontBase); });
    drawLabels(ctx, panels, w, h, focused, fontBase);

    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { display: false, min: 0, max: 1 },
      y: { display: false, min: 0, max: 1 }
    }
  },
  plugins: [capacityPlugin]
});
window.__markRendered();

function panelAtEvent(evt) {
  var r = canvas.getBoundingClientRect();
  var x = (evt.clientX - r.left) * (canvas.width / r.width);
  var y = (evt.clientY - r.top) * (canvas.height / r.height);
  for (var i = 0; i < lastPanels.length; i++) {
    var p = lastPanels[i];
    if (x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h) return p;
  }
  return null;
}

canvas.addEventListener('mousemove', function(evt) {
  var p = panelAtEvent(evt);
  if (p) {
    canvas.style.cursor = 'pointer';
    var name = p.index === 0 ? 'reference data and target function' : (p.units + ' hidden units');
    showTooltip('Click to inspect ' + name + '. Black: target trend; orange: training data; cyan: fitted network.', evt);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
  }
});

canvas.addEventListener('mouseleave', function() {
  canvas.style.cursor = 'default';
  hideTooltip();
});

canvas.addEventListener('click', function(evt) {
  var p = panelAtEvent(evt);
  if (!p) return;
  if (state.focused && state.focused.index === p.index && state.focused.units === p.units) {
    state.focused = null;
  } else {
    state.focused = {
      index: p.index,
      units: p.units,
      letter: p.letter || '',
      title: p.title || (p.index === 0 ? '' : p.units + ' hidden units')
    };
    var title = p.index === 0 ? 'Reference panel' : p.units + ' hidden units';
    var body = p.index === 0
      ? 'This panel shows the training samples and the smooth target relationship. It is the baseline for judging each fitted neural-network curve.'
      : 'This panel isolates one network capacity. Compare the cyan fit to the orange points and the black target curve: more hidden units allow more shape complexity.';
    showPopup(title, body);
  }
  chart.update('none');
});

function update_hiddenUnitCount(v) {
  state.selectedUnits = v;
  state.focused = {
    index: -1,
    units: v,
    letter: '',
    title: v + ' hidden units'
  };
  chart.update('none');
}

function toggle_fitComparison(on) {
  state.compare = !!on;
  state.focused = null;
  chart.update('none');
}

function trigger_resetView() {
  state.focused = null;
  hidePopup();
  chart.update('none');
}

var demoSteps = [
  {
    title: 'Reference data and target trend',
    narration: 'The orange points are the training observations, while the black curve shows the smooth underlying relationship the model is trying to approximate.',
    state: { hiddenUnitCount: 6, fitComparison: '6 hidden units' }
  },
  {
    title: 'Low hidden-unit count',
    narration: 'With 6 hidden units, the cyan network fit has limited flexibility and uses a small number of broad piecewise segments to pass near the data.',
    state: { hiddenUnitCount: 6, fitComparison: '6 hidden units' }
  },
  {
    title: 'Intermediate capacity',
    narration: 'As the slider moves through 7, 8, and 10 hidden units, the fitted curve gains more degrees of freedom and can better adapt to local structure in the observations.',
    state: { hiddenUnitCount: 10, fitComparison: '6 hidden units' }
  },
  {
    title: 'High hidden-unit count',
    narration: 'At 50 hidden units, the network has enough capacity to trace a much smoother and more detailed approximation of the target curve while still matching the training points.',
    state: { hiddenUnitCount: 50, fitComparison: '50 hidden units' }
  },
  {
    title: 'Inspect one panel closely',
    narration: 'Click any panel to enlarge that hidden-unit setting and compare the cyan fitted curve against both the orange observations and the black reference function.',
    state: { hiddenUnitCount: 50, fitComparison: '50 hidden units' }
  }
];

function applyStep(i) {
  state.step = clamp(i, 0, demoSteps.length - 1);
  var step = demoSteps[state.step];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + ' / ' + demoSteps.length;

  var units = step.state.hiddenUnitCount;
  var slider = document.getElementById('hiddenUnitCountInput');
  var out = document.getElementById('hiddenUnitCountVal');
  slider.value = units;
  out.value = units;
  state.selectedUnits = units;

  var compareOn = step.state.fitComparison === '50 hidden units';
  var chk = document.getElementById('fitComparisonInput');
  chk.checked = compareOn;
  state.compare = compareOn;

  if (state.step === 0) {
    state.focused = null;
  } else if (state.step === 1) {
    state.focused = { index: 1, units: 6, letter: 'b)', title: '6 hidden units' };
  } else if (state.step === 2) {
    state.focused = { index: 4, units: 10, letter: 'e)', title: '10 hidden units' };
  } else if (state.step === 3) {
    state.focused = { index: 5, units: 50, letter: 'f)', title: '50 hidden units' };
  } else {
    state.focused = null;
  }
  chart.update('none');
}

function nextStep() { applyStep(state.step + 1); }
function prevStep() { applyStep(state.step - 1); }

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Increasing the number of hidden units in a shallow neural network changes the capacity of the fitted function, altering how smoothly or intricately it can match the observed training data.
KEY INSIGHT (what students should walk away understanding): Hidden units are the capacity knob: changing their number changes how much shape complexity the shallow network can express.
DEMO STEPS: 5 guided steps — implement the step player in #ui

