    [0.25,0.75],[0.38,0.55],[0.50,-0.08],[0.63,-0.62],
    [0.75,-0.85],[0.87,-0.39],[0.93,-0.43],[1.00,-0.47]
  ],
  10: [
    [0.00,-0.18],[0.07,0.02],[0.12,0.19],[0.19,0.47],
    [0.29,0.58],[0.40,0.39],[0.52,-0.05],[0.62,-0.44],
    [0.72,-0.61],[0.82,-0.62],[0.90,-0.45],[0.96,-0.40],[1.00,-0.47]
  ],
  50: [
    [0.00,-0.18],[0.06,-0.04],[0.12,0.20],[0.19,0.47],
    [0.27,0.62],[0.36,0.56],[0.47,0.24],[0.58,-0.22],
    [0.68,-0.55],[0.77,-0.70],[0.86,-0.61],[0.92,-0.43],[1.00,-0.47]
  ]
};

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

function catmullAt(pts, x) {
  if (x <= pts[0][0]) return pts[0][1];
  if (x >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  var i = 0;
  while (i < pts.length - 2 && pts[i + 1][0] < x) i++;
  var p0 = pts[Math.max(0, i - 1)];
  var p1 = pts[i];
  var p2 = pts[i + 1];
  var p3 = pts[Math.min(pts.length - 1, i + 2)];
  var t = (x - p1[0]) / (p2[0] - p1[0]);
  var t2 = t * t, t3 = t2 * t;
  return 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2*p0[1] - 5*p1[1] + 4*p2[1] - p3[1]) * t2 + (-p0[1] + 3*p1[1] - 3*p2[1] + p3[1]) * t3);
}

function linearAt(pts, x) {
  if (x <= pts[0][0]) return pts[0][1];
  if (x >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  for (var i = 0; i < pts.length - 1; i++) {
    if (x >= pts[i][0] && x <= pts[i + 1][0]) {
      var t = (x - pts[i][0]) / (pts[i + 1][0] - pts[i][0]);
      return pts[i][1] * (1 - t) + pts[i + 1][1] * t;
    }
  }
  return pts[pts.length - 1][1];
}

function targetY(x) { return catmullAt(targetAnchors, x); }

function fitYForUnits(units, x) {
  units = clamp(units, 6, 50);
  if (fitAnchors[units]) return units === 50 ? catmullAt(fitAnchors[50], x) : linearAt(fitAnchors[units], x);
  var lower, upper;
  if (units < 7) { lower = 6; upper = 7; }
  else if (units < 8) { lower = 7; upper = 8; }
  else if (units < 10) { lower = 8; upper = 10; }
  else { lower = 10; upper = 50; }
  var t = (units - lower) / (upper - lower);
  t = t * t * (3 - 2 * t);
  var yl = lower === 50 ? catmullAt(fitAnchors[50], x) : linearAt(fitAnchors[lower], x);
  var yu = upper === 50 ? catmullAt(fitAnchors[50], x) : linearAt(fitAnchors[upper], x);
  return yl * (1 - t) + yu * t;
}

var state = {
  focused: null,
  selectedUnits: 6,
  compare: false,
  step: 0
};

var lastPanels = [];

function measureTextWidth(ctx, text, font) {
  ctx.save();
  ctx.font = font;
  var w = ctx.measureText(text).width;
  ctx.restore();
  return w;
}

function makeMetrics(w, h) {
  var scale = clamp(Math.min(w / 1160, h / 720), 0.48, 1.18);
  return {
    scale: scale,
    tickFont: clamp(20 * scale, 9.5, 21),
    axisFont: clamp(34 * scale, 15, 34),
    titleFontRaw: clamp(34 * scale, 14, 34),
    letterFont: clamp(40 * scale, 18, 40),
    lineW: clamp(6 * scale, 3.0, 6.5),
    fitW: clamp(6 * scale, 3.0, 6.5),
    pointR: clamp(11 * scale, 4.2, 11),
    borderW: clamp(3.0 * scale, 1.8, 3.2),
    tickW: clamp(2.0 * scale, 1.0, 2.0)
  };
}

function layoutPanels(w, h, focused, ctx) {
  var m = makeMetrics(w, h);
  var focusedTitle = focused ? (focused.title || '') : '';
  var maxTitle = focused ? focusedTitle : '50 hidden units';
  var leftNeeded = Math.max(60, m.axisFont * 2.9 + m.tickFont * 1.3);
  var right = Math.max(8, 14 * m.scale);
  var gx = Math.max(18, w * 0.032);
  var titleFontForWidth;
  var widthBased;
  var top, bottom, gy, maxPwByH, pw, ph, blockW, extraX, x0, y0;

  if (focused) {
    var fLeft = Math.max(66, m.axisFont * 2.75 + m.tickFont * 1.3);
    var fTop = Math.max(34, m.titleFontRaw * 1.45);
    var fBottom = Math.max(48, m.axisFont * 1.95 + m.tickFont * 1.5);
    var availW = Math.max(60, w - fLeft - right);
    var availH = Math.max(60, h - fTop - fBottom);
    pw = Math.min(availW, availH * 1.24);
    ph = pw / 1.24;
    x0 = fLeft + Math.max(0, (availW - pw) / 2);
    y0 = fTop + Math.max(0, (availH - ph) / 2);
    titleFontForWidth = maxTitle ? Math.min(m.titleFontRaw, pw * 0.92 / (maxTitle.length * 0.54)) : m.titleFontRaw;
    return [{
      x: x0, y: y0, w: pw, h: ph,
      index: focused.index == null ? -1 : focused.index,
      units: focused.units,
      letter: focused.letter || '',
      title: focused.title || '',
      metrics: m,
      titleFont: clamp(titleFontForWidth, 13, 36)
    }];
  }

  widthBased = (w - leftNeeded - right - 2 * gx) / 3;
  titleFontForWidth = Math.min(m.titleFontRaw, Math.max(12, widthBased) * 0.90 / (maxTitle.length * 0.54));
  titleFontForWidth = clamp(titleFontForWidth, 12.5, m.titleFontRaw);
  top = Math.max(30, titleFontForWidth * 1.55);
  bottom = Math.max(42, m.axisFont * 1.75 + m.tickFont * 1.15);
  gy = Math.max(38, titleFontForWidth * 1.65 + m.tickFont * 1.25);
  maxPwByH = Math.max(50, (h - top - bottom - gy) * 1.24 / 2);
  pw = Math.max(48, Math.min(widthBased, maxPwByH));
  ph = pw / 1.24;
  blockW = 3 * pw + 2 * gx;
  extraX = Math.max(0, w - leftNeeded - right - blockW);
  x0 = leftNeeded + extraX / 2;
  y0 = top + Math.max(0, (h - top - bottom - gy - 2 * ph) / 2);

  var panels = [];
  var letters = ['a)', 'b)', 'c)', 'd)', 'e)', 'f)'];
  var titles = ['', '6 hidden units', '7 hidden units', '8 hidden units', '10 hidden units', '50 hidden units'];
  var units = [null, 6, 7, 8, 10, 50];
  for (var r = 0; r < 2; r++) {
    for (var c = 0; c < 3; c++) {
      var idx = r * 3 + c;
      panels.push({
        x: x0 + c * (pw + gx),
        y: y0 + r * (ph + gy),
        w: pw, h: ph,
        index: idx,
        units: units[idx],
        letter: letters[idx],
        title: titles[idx],
        metrics: m,
        titleFont: titleFontForWidth
      });
    }
  }
  return panels;
}

function panelScale(panel) {
  return {
    x: function(v) { return panel.x + v * panel.w; },
    y: function(v) { return panel.y + panel.h - ((v + 1) / 2) * panel.h; }
  };
}

function sampledPts(fn, n) {
  var pts = [];
  for (var i = 0; i < n; i++) {
    var x = i / (n - 1);
    pts.push([x, fn(x)]);
  }
  return pts;
}

function fitPts(units) {
  if (fitAnchors[units] && units !== 50) return fitAnchors[units];
  var n = units >= 35 ? 170 : 100;
  return sampledPts(function(x) { return fitYForUnits(units, x); }, n);
}

function drawPolyline(ctx, panel, pts, color, width, alpha) {
  var sc = panelScale(panel);
  ctx.save();
  ctx.beginPath();
  ctx.rect(panel.x, panel.y, panel.w, panel.h);
  ctx.clip();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    var px = sc.x(pts[i][0]), py = sc.y(pts[i][1]);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();
}

function drawAxes(ctx, panel) {
  var m = panel.metrics;
  var tickLen = Math.max(3, m.tickFont * 0.34);
  var minorLen = Math.max(2, m.tickFont * 0.22);

  ctx.save();

  if (state.compare && (panel.units === 6 || panel.units === 50)) {
    ctx.fillStyle = 'rgba(255, 232, 150, 0.20)';
    ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
  }

  ctx.strokeStyle = BLACK;
  ctx.lineWidth = m.borderW;
  ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

  ctx.strokeStyle = GREY;
  ctx.lineWidth = m.tickW;
  for (var i = 0; i <= 10; i++) {
    var x = panel.x + panel.w * i / 10;
    ctx.beginPath();
    ctx.moveTo(x, panel.y + panel.h);
    ctx.lineTo(x, panel.y + panel.h + (i % 5 === 0 ? tickLen : minorLen));
    ctx.stroke();
  }
  for (var j = 0; j <= 10; j++) {
    var y = panel.y + panel.h * j / 10;
    ctx.beginPath();
    ctx.moveTo(panel.x, y);
    ctx.lineTo(panel.x - (j % 5 === 0 ? tickLen : minorLen), y);
    ctx.stroke();
  }

  ctx.fillStyle = GREY;
  ctx.font = m.tickFont + 'px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  [0, 0.5, 1.0].forEach(function(v) {
    ctx.fillText(v.toFixed(1), panel.x + panel.w * v, panel.y + panel.h + tickLen + Math.max(2, m.tickFont * 0.12));
  });

  if (panel.index % 3 === 0 || panel.index < 0) {
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    [-1, 0, 1].forEach(function(v) {
      ctx.fillText(v.toFixed(1), panel.x - tickLen - Math.max(4, m.tickFont * 0.22), panel.y + panel.h - ((v + 1) / 2) * panel.h);
    });
  }

  ctx.restore();
}

function drawPanelContent(ctx, panel) {
  var m = panel.metrics;
  var dim = state.compare && panel.units && panel.units !== 6 && panel.units !== 50 ? 0.30 : 1;

  drawAxes(ctx, panel);
  drawPolyline(ctx, panel, sampledPts(targetY, 190), BLACK, m.lineW, dim);

  if (panel.units) {
    var isExtreme = state.compare && (panel.units === 6 || panel.units === 50);
    drawPolyline(ctx, panel, fitPts(panel.units), CYAN, isExtreme ? m.fitW * 1.12 : m.fitW, dim);
  }

  var sc = panelScale(panel);
  ctx.save();
  ctx.globalAlpha = dim;
  trainPts.forEach(function(p) {
    ctx.beginPath();
    ctx.arc(sc.x(p[0]), sc.y(p[1]), m.pointR, 0, Math.PI * 2);
    ctx.fillStyle = ORANGE;
    ctx.fill();
  });
  ctx.restore();
}

function drawLabels(ctx, panels, focused) {
  ctx.save();
  ctx.fillStyle = BLACK;

  panels.forEach(function(panel) {
    var m = panel.metrics;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = m.letterFont + 'px Arial, sans-serif';
    var lx = panel.x - m.letterFont * 1.85;
    if (lx < 1) lx = 1;
    var ly = panel.y - Math.max(8, panel.titleFont * 0.58);
    ctx.fillText(panel.letter, lx, ly);

    if (panel.title) {
      ctx.textAlign = 'center';
      ctx.font = panel.titleFont + 'px Arial, sans-serif';
      ctx.fillText(panel.title, panel.x + panel.w / 2, panel.y - Math.max(8, panel.titleFont * 0.52));
    }
  });

  var bottomPanels = focused ? panels : panels.filter(function(p) { return p.index >= 3; });
  bottomPanels.forEach(function(panel) {
    var m = panel.metrics;
    var y = panel.y + panel.h + Math.max(27, m.axisFont * 1.55);
    ctx.textBaseline = 'top';
    ctx.textAlign = 'center';
    ctx.font = m.axisFont + 'px Arial, sans-serif';
    ctx.fillText('Input, ', panel.x + panel.w / 2 - m.axisFont * 0.30, y);
    ctx.font = 'italic ' + m.axisFont + 'px Georgia, serif';
    ctx.fillText('x', panel.x + panel.w / 2 + m.axisFont * 2.12, y);
  });

  var yLabelPanels = focused ? panels : panels.filter(function(p) { return p.index % 3 === 0; });
  yLabelPanels.forEach(function(panel) {
    var m = panel.metrics;
    ctx.save();
    var x = Math.max(m.axisFont * 0.70, panel.x - m.axisFont * 2.28);
    ctx.translate(x, panel.y + panel.h / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = m.axisFont + 'px Arial, sans-serif';
    ctx.fillText('Output, ', -m.axisFont * 0.40, 0);
    ctx.font = 'italic ' + m.axisFont + 'px Georgia, serif';
    ctx.fillText('y', m.axisFont * 2.78, 0);
    ctx.restore();
  });

  ctx.restore();
}

var capacityPlugin = {
  id: 'capacitySmallMultiples',
  afterDraw: function(chart) {
    var ctx = chart.ctx;
    var w = chart.width;
    var h = chart.height;

    ctx.save();
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);

    var panels = layoutPanels(w, h, state.focused, ctx);
    lastPanels = panels;

    panels.forEach(function(panel) { drawPanelContent(ctx, panel); });
    drawLabels(ctx, panels, !!state.focused);

    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { display: false, min: 0, max: 1 },
      y: { display: false, min: 0, max: 1 }
    }
  },
  plugins: [capacityPlugin]
});
window.__markRendered();

function panelAtEvent(evt) {
  var r = canvas.getBoundingClientRect();
  var x = (evt.clientX - r.left) * (chart.width / r.width);
  var y = (evt.clientY - r.top) * (chart.height / r.height);
  for (var i = 0; i < lastPanels.length; i++) {
    var p = lastPanels[i];
    if (x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h) return p;
  }
  return null;
}

canvas.addEventListener('mousemove', function(evt) {
  var p = panelAtEvent(evt);
  if (p) {
    canvas.style.cursor = 'pointer';
    var name = p.index === 0 ? 'reference data and target function' : (p.units + ' hidden units');
    showTooltip('Click to inspect ' + name + '. Black: target trend; orange: training data; cyan: fitted network.', evt);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
  }
});

canvas.addEventListener('mouseleave', function() {
  canvas.style.cursor = 'default';
  hideTooltip();
});

canvas.addEventListener('click', function(evt) {
  var p = panelAtEvent(evt);
  if (!p) return;
  if (state.focused && state.focused.index === p.index && state.focused.units === p.units) {
    state.focused = null;
    hidePopup();
  } else {
    state.focused = {
      index: p.index,
      units: p.units,
      letter: p.letter || '',
      title: p.title || (p.index === 0 ? '' : p.units + ' hidden units')
    };
    var title = p.index === 0 ? 'Reference panel' : p.units + ' hidden units';
    var body = p.index === 0
      ? 'This panel shows the training samples and the smooth target relationship. It is the baseline for judging each fitted neural-network curve.'
      : 'This panel isolates one network capacity. Compare the cyan fit to the orange points and the black target curve: more hidden units allow more shape complexity.';
    showPopup(title, body);
  }
  chart.update('none');
});

function update_hiddenUnitCount(v) {
  state.selectedUnits = v;
  state.focused = {
    index: -1,
    units: v,
    letter: '',
    title: v + ' hidden units'
  };
  chart.update('none');
}

function toggle_fitComparison(on) {
  state.compare = !!on;
  state.focused = null;
  chart.update('none');
}

function trigger_resetView() {
  state.focused = null;
  hidePopup();
  chart.update('none');
}

var demoSteps = [
  {
    title: 'Reference data and target trend',
    narration: 'The orange points are the training observations, while the black curve shows the smooth underlying relationship the model is trying to approximate.',
    state: { hiddenUnitCount: 6, fitComparison: '6 hidden units' }
  },
  {
    title: 'Low hidden-unit count',
    narration: 'With 6 hidden units, the cyan network fit has limited flexibility and uses a small number of broad piecewise segments to pass near the data.',
    state: { hiddenUnitCount: 6, fitComparison: '6 hidden units' }
  },
  {
    title: 'Intermediate capacity',
    narration: 'As the slider moves through 7, 8, and 10 hidden units, the fitted curve gains more degrees of freedom and can better adapt to local structure in the observations.',
    state: { hiddenUnitCount: 10, fitComparison: '6 hidden units' }
  },
  {
    title: 'High hidden-unit count',
    narration: 'At 50 hidden units, the network has enough capacity to trace a much smoother and more detailed approximation of the target curve while still matching the training points.',
    state: { hiddenUnitCount: 50, fitComparison: '50 hidden units' }
  },
  {
    title: 'Inspect one panel closely',
    narration: 'Click any panel to enlarge that hidden-unit setting and compare the cyan fitted curve against both the orange observations and the black reference function.',
    state: { hiddenUnitCount: 50, fitComparison: '50 hidden units' }
  }
];

function setSliderUnits(units) {
  var slider = document.getElementById('hiddenUnitCountInput');
  var out = document.getElementById('hiddenUnitCountVal');
  if (slider) slider.value = units;
  if (out) out.value = units;
  state.selectedUnits = units;
}

function applyStep(i) {
  state.step = clamp(i, 0, demoSteps.length - 1);
  var step = demoSteps[state.step];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + ' / ' + demoSteps.length;

  var units = step.state.hiddenUnitCount;
  setSliderUnits(units);

  var compareOn = step.state.fitComparison === '50 hidden units';
  var chk = document.getElementById('fitComparisonInput');
  if (chk) chk.checked = compareOn;
  state.compare = compareOn;

  if (state.step === 0) {
    state.focused = null;
  } else if (state.step === 1) {
    state.focused = { index: 1, units: 6, letter: 'b)', title: '6 hidden units' };
  } else if (state.step === 2) {
    state.focused = { index: 4, units: 10, letter: 'e)', title: '10 hidden units' };
  } else if (state.step === 3) {
    state.focused = { index: 5, units: 50, letter: 'f)', title: '50 hidden units' };
  } else {
    state.focused = null;
  }
  chart.update('none');
}

function nextStep() { applyStep(state.step + 1); }
function prevStep() { applyStep(state.step - 1); }

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Increasing the number of hidden units in a shallow neural network changes the capacity of the fitted function, altering how smoothly or intricately it can match the observed training data.
KEY INSIGHT (what students should walk away understanding): Hidden units are the capacity knob: changing their number changes how much shape complexity the shallow network can express.
DEMO STEPS: 5 guided steps — implement the step player in #ui

