var lastPanels = [];

function makeMetrics(w, h) {
  var scale = clamp(Math.min(w / 1160, h / 720), 0.46, 1.18);
  return {
    scale: scale,
    tickFont: clamp(20 * scale, 9.0, 21),
    axisFont: clamp(34 * scale, 14, 34),
    titleFontRaw: clamp(34 * scale, 14, 34),
    letterFont: clamp(40 * scale, 17, 40),
    lineW: clamp(6 * scale, 2.7, 6.5),
    fitW: clamp(6 * scale, 2.7, 6.5),
    pointR: clamp(11 * scale, 4.0, 11),
    borderW: clamp(3.0 * scale, 1.55, 3.2),
    tickW: clamp(2.0 * scale, 0.9, 2.0)
