}

function layoutPanels(w, h, focused) {
  var m = makeMetrics(w, h);
  var right = Math.max(3, 8 * m.scale);
  var leftNeeded = Math.max(45, m.axisFont * 2.25 + m.tickFont * 1.05);
  var gx = Math.max(12, w * 0.026);
  var maxTitle = focused ? (focused.title || '') : '50 hidden units';
  var titleFontForWidth, widthBased, top, bottom, gy, maxPwByH, pw, ph, blockW, extraX, x0, y0;

  if (focused) {
    var fLeft = Math.max(52, m.axisFont * 2.35 + m.tickFont * 1.05);
    var fTop = Math.max(28, m.titleFontRaw * 1.38);
    var fBottom = Math.max(42, m.axisFont * 1.75 + m.tickFont * 1.2);
    var availW = Math.max(70, w - fLeft - right);
    var availH = Math.max(70, h - fTop - fBottom);
    pw = Math.min(availW, availH * 1.24);
    ph = pw / 1.24;
    x0 = fLeft + Math.max(0, (availW - pw) / 2);
    y0 = fTop + Math.max(0, (availH - ph) / 2);
    titleFontForWidth = maxTitle ? Math.min(m.titleFontRaw, pw * 0.86 / (maxTitle.length * 0.54)) : m.titleFontRaw;
    return [{
      x: x0, y: y0, w: pw, h: ph,
      index: focused.index == null ? -1 : focused.index,
      units: focused.units,
      letter: focused.letter || '',
      title: focused.title || '',
      metrics: m,
      titleFont: clamp(titleFontForWidth, 13, 36)
    }];
  }

  widthBased = (w - leftNeeded - right - 2 * gx) / 3;
  titleFontForWidth = Math.min(m.titleFontRaw, Math.max(12, widthBased) * 0.86 / (maxTitle.length * 0.54));
  titleFontForWidth = clamp(titleFontForWidth, 12, m.titleFontRaw);
  top = Math.max(26, titleFontForWidth * 1.35);
  bottom = Math.max(38, m.axisFont * 1.55 + m.tickFont * 1.05);
  gy = Math.max(30, titleFontForWidth * 1.35 + m.tickFont * 0.95);
  maxPwByH = Math.max(50, (h - top - bottom - gy) * 1.24 / 2);
  pw = Math.max(48, Math.min(widthBased, maxPwByH));
  ph = pw / 1.24;
  blockW = 3 * pw + 2 * gx;
  extraX = Math.max(0, w - leftNeeded - right - blockW);
  x0 = leftNeeded + extraX / 2;
  y0 = top;

  var totalH = top + 2 * ph + gy + bottom;
  if (totalH < h * 0.72) y0 = Math.max(top, Math.min(h * 0.12, top + (h * 0.72 - totalH) * 0.15));

  var panels = [];
  var letters = ['a)', 'b)', 'c)', 'd)', 'e)', 'f)'];
  var titles = ['', '6 hidden units', '7 hidden units', '8 hidden units', '10 hidden units', '50 hidden units'];
  var units = [null, 6, 7, 8, 10, 50];
  for (var r = 0; r < 2; r++) {
    for (var c = 0; c < 3; c++) {
      var idx = r * 3 + c;
      panels.push({
        x: x0 + c * (pw + gx),
        y: y0 + r * (ph + gy),
        w: pw, h: ph,
        index: idx,
        units: units[idx],
        letter: letters[idx],
        title: titles[idx],
        metrics: m,
        titleFont: titleFontForWidth
