}

function panelScale(panel) {
  return {
    x: function(v) { return panel.x + v * panel.w; },
    y: function(v) { return panel.y + panel.h - ((v + 1) / 2) * panel.h; }
  };
}

function sampledPts(fn, n) {
  var pts = [];
  for (var i = 0; i < n; i++) {
    var x = i / (n - 1);
    pts.push([x, fn(x)]);
  }
  return pts;
}

function fitPts(units) {
