  var n = units >= 35 ? 180 : 100;
  return sampledPts(function(x) { return fitYForUnits(units, x); }, n);
}

function drawPolyline(ctx, panel, pts, color, width, alpha) {
  var sc = panelScale(panel);
  ctx.save();
  ctx.beginPath();
  ctx.rect(panel.x, panel.y, panel.w, panel.h);
  ctx.clip();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    var px = sc.x(pts[i][0]), py = sc.y(pts[i][1]);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();
}

function drawAxes(ctx, panel) {
  var m = panel.metrics;
  var tickLen = Math.max(3, m.tickFont * 0.34);
  var minorLen = Math.max(2, m.tickFont * 0.22);

  ctx.save();

  if (state.compare && (panel.units === 6 || panel.units === 50)) {
    ctx.fillStyle = 'rgba(255, 232, 150, 0.20)';
    ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
  }

  ctx.strokeStyle = BLACK;
  ctx.lineWidth = m.borderW;
  ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

  ctx.strokeStyle = GREY;
  ctx.lineWidth = m.tickW;
  for (var i = 0; i <= 10; i++) {
    var x = panel.x + panel.w * i / 10;
    ctx.beginPath();
    ctx.moveTo(x, panel.y + panel.h);
    ctx.lineTo(x, panel.y + panel.h + (i % 5 === 0 ? tickLen : minorLen));
    ctx.stroke();
  }
  for (var j = 0; j <= 10; j++) {
    var y = panel.y + panel.h * j / 10;
    ctx.beginPath();
    ctx.moveTo(panel.x, y);
    ctx.lineTo(panel.x - (j % 5 === 0 ? tickLen : minorLen), y);
    ctx.stroke();
  }

  ctx.fillStyle = GREY;
  ctx.font = m.tickFont + 'px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  [0, 0.5, 1.0].forEach(function(v) {
    ctx.fillText(v.toFixed(1), panel.x + panel.w * v, panel.y + panel.h + tickLen + Math.max(1.5, m.tickFont * 0.10));
  });

  if (panel.index % 3 === 0 || panel.index < 0) {
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    [-1, 0, 1].forEach(function(v) {
      ctx.fillText(v.toFixed(1), panel.x - tickLen - Math.max(3, m.tickFont * 0.18), panel.y + panel.h - ((v + 1) / 2) * panel.h);
    });
  }

  ctx.restore();
}

function drawPanelContent(ctx, panel) {
  var m = panel.metrics;
  var dim = state.compare && panel.units && panel.units !== 6 && panel.units !== 50 ? 0.30 : 1;

  drawAxes(ctx, panel);
  drawPolyline(ctx, panel, sampledPts(targetY, 190), BLACK, m.lineW, dim);

  if (panel.units) {
    var isExtreme = state.compare && (panel.units === 6 || panel.units === 50);
    drawPolyline(ctx, panel, fitPts(panel.units), CYAN, isExtreme ? m.fitW * 1.12 : m.fitW, dim);
  }

  var sc = panelScale(panel);
  ctx.save();
  ctx.globalAlpha = dim;
  trainPts.forEach(function(p) {
    ctx.beginPath();
    ctx.arc(sc.x(p[0]), sc.y(p[1]), m.pointR, 0, Math.PI * 2);
    ctx.fillStyle = ORANGE;
    ctx.fill();
  });
  ctx.restore();
}

function drawLabels(ctx, panels, focused) {
  ctx.save();
  ctx.fillStyle = BLACK;

  panels.forEach(function(panel) {
    var m = panel.metrics;
    var titleY = panel.y - Math.max(8, panel.titleFont * 0.42);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = m.letterFont + 'px Arial, sans-serif';
    var lx = panel.x - m.letterFont * 1.03;
    if (panel.index % 3 === 0 || panel.index < 0) lx = panel.x - m.letterFont * 1.70;
    if (lx < 1) lx = 1;
    ctx.fillText(panel.letter, lx, titleY);

    if (panel.title) {
      ctx.textAlign = 'center';
      ctx.font = panel.titleFont + 'px Arial, sans-serif';
      ctx.fillText(panel.title, panel.x + panel.w / 2, titleY);
    }
  });

  var bottomPanels = focused ? panels : panels.filter(function(p) { return p.index >= 3; });
  bottomPanels.forEach(function(panel) {
    var m = panel.metrics;
    var y = panel.y + panel.h + Math.max(22, m.axisFont * 1.35);
    ctx.textBaseline = 'top';
    ctx.textAlign = 'center';
    ctx.font = m.axisFont + 'px Arial, sans-serif';
    ctx.fillText('Input, ', panel.x + panel.w / 2 - m.axisFont * 0.26, y);
    ctx.font = 'italic ' + m.axisFont + 'px Georgia, serif';
    ctx.fillText('x', panel.x + panel.w / 2 + m.axisFont * 2.08, y);
  });

  var yLabelPanels = focused ? panels : panels.filter(function(p) { return p.index % 3 === 0; });
  yLabelPanels.forEach(function(panel) {
    var m = panel.metrics;
    ctx.save();
    var x = Math.max(m.axisFont * 0.62, panel.x - m.axisFont * 2.02);
    ctx.translate(x, panel.y + panel.h / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = m.axisFont + 'px Arial, sans-serif';
    ctx.fillText('Output, ', -m.axisFont * 0.34, 0);
    ctx.font = 'italic ' + m.axisFont + 'px Georgia, serif';
    ctx.fillText('y', m.axisFont * 2.77, 0);
    ctx.restore();
  });

